'use strict';
const CommunityUI=(()=>{
  const names={carrot:'몽글당근',cotton:'폭신목화',butterfly:'나비',dragonfly:'잠자리',chest:'보물상자'},sellers={mori:'모리',nari:'나리',me:'포근이'},stamps={kind:'친절해요',lovely:'마음에 쏙!',quick:'깔끔한 거래'};
  const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let tab='stalls',seller='mori',message='취향이 오가는 작은 마을 장터';
  function feedback(r){message=r.message+(economy.storageOK?'':' · 저장 불가: 이번 방문에만 유지');render()}
  function market(){economy.settleMarket();modal('마을 광장 플리마켓','<div id="marketRoot"></div>');$('#modal').classList.add('wardrobe-modal');render()}
  function render(){const root=$('#marketRoot');if(!root)return;const d=economy.data,m=d.market;
    root.innerHTML=`<div class="boutique-heading"><p>물건에도, 마음에도 다음 이야기가 있어요.</p><b>◒ ${d.shells.toLocaleString()}</b></div><div class="wardrobe-tabs">${[['stalls','이웃 가판대'],['mine','나의 무인 가판대'],['book','후기 공책']].map(([id,name])=>`<button data-market-tab="${id}" aria-pressed="${tab===id}">${name}</button>`).join('')}</div><p class="local-caption">혼자 즐기는 연습 장터예요. 이웃은 가상 주민이며 거래는 이 브라우저에 저장됩니다.</p><div id="marketContent"></div><p class="fashion-status" role="status">${escape(message)}</p>`;
    document.querySelectorAll('[data-market-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.marketTab;render()});
    if(tab==='stalls'){$('#marketContent').innerHTML=`<div class="stall-grid">${economy.stalls.map(s=>`<article class="stall"><div class="awning"></div><small>${s.name}</small><h3>${names[s.item]} × ${s.quantity}</h3><b>${s.price} 조개</b><p>판매자 ${sellers[s.seller]}</p><button class="primary" data-buy-stall="${s.id}" ${m.sold.includes(s.id)?'disabled':''}>${m.sold.includes(s.id)?'판매 완료':'무인 구매하기'}</button><button class="book-link" data-book="${s.seller}">후기 공책 ↗</button></article>`).join('')}</div>`;document.querySelectorAll('[data-buy-stall]').forEach(b=>b.onclick=()=>{const r=economy.buyStall(b.dataset.buyStall);if(r.ok){seller=economy.stalls.find(s=>s.id===b.dataset.buyStall).seller;tab='book'}feedback(r)});document.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>{seller=b.dataset.book;tab='book';render()})}
    if(tab==='mine'){$('#marketContent').innerHTML=`<form id="listingForm" class="listing-form"><label>판매할 물건<select id="listingItem">${economy.tradable.map(k=>`<option value="${k}">${names[k]} · 보유 ${d.inventory[k]}</option>`).join('')}</select></label><label>수량<input id="listingQuantity" type="number" min="1" max="99" value="1" required></label><label>묶음 가격 (조개)<input id="listingPrice" type="number" min="1" max="99999" value="50" required></label><button class="primary" type="submit">가판대에 진열</button></form><p class="local-caption">진열 시 물건을 보관하고, 20초 뒤 연습 주민이 구매합니다. 판매 대금은 직접 정산하세요. 판매 전에는 회수할 수 있어요.</p><div class="listing-history">${m.listings.slice().reverse().map(l=>`<div class="listing-row"><div><b>${names[l.item]} × ${l.quantity}</b><small>${l.price} 조개 · ${l.status==='listed'?'진열 중':l.status==='sold'?'판매 완료 · 미정산':l.status==='claimed'?'정산 완료':'회수 완료'}</small></div>${l.status==='listed'?`<button data-cancel-listing="${l.id}">회수</button>`:l.status==='sold'?`<button data-collect-sale="${l.id}">판매 대금 받기</button>`:''}</div>`).join('')||'<p>첫 물건을 진열해 보세요.</p>'}</div><button class="item" id="myBook">내 후기 공책 보기 →</button>`;
      $('#listingForm').onsubmit=e=>{e.preventDefault();feedback(economy.listItem($('#listingItem').value,Number($('#listingQuantity').value),Number($('#listingPrice').value)))};document.querySelectorAll('[data-cancel-listing]').forEach(b=>b.onclick=()=>feedback(economy.cancelListing(Number(b.dataset.cancelListing))));document.querySelectorAll('[data-collect-sale]').forEach(b=>b.onclick=()=>feedback(economy.collectSale(Number(b.dataset.collectSale))));$('#myBook').onclick=()=>{seller='me';tab='book';render()}}
    if(tab==='book'){
      const reviews=m.reviews.filter(r=>m.trades.some(t=>t.id===r.tradeId&&t.seller===seller));const eligible=m.trades.filter(t=>t.seller===seller&&t.buyer==='me'&&!m.reviews.some(r=>r.tradeId===t.id));
      $('#marketContent').innerHTML=`<div class="wardrobe-tabs seller-tabs">${Object.entries(sellers).map(([id,name])=>`<button data-seller="${id}" aria-pressed="${seller===id}">${name}의 공책</button>`).join('')}</div><section class="notebook"><div class="notebook-binding"></div><header class="notebook-heading"><span>마음을 모으는 공책</span><h3>${sellers[seller]}의 거래 이야기</h3><b>칭찬 도장 ${reviews.length}개 · ${reviews.length>=3?'포근한 이웃 상인':'새싹 상인'}</b></header><div class="notebook-entries">${reviews.map(r=>`<article class="handwritten"><span class="praise-stamp">${stamps[r.stamp]}</span><p>${escape(r.text)}</p><small>거래 #${r.tradeId} · ${m.trades.find(t=>t.id===r.tradeId).buyer==='me'?'포근이':'연습 주민 나리'}</small></article>`).join('')||'<p class="blank-page">아직 빈 페이지예요.<br>첫 번째 따뜻한 마음을 기다려요.</p>'}</div></section>${eligible.length?`<form id="reviewForm" class="review-form"><label>완료한 거래<select id="reviewTrade">${eligible.map(t=>`<option value="${t.id}">#${t.id} · ${names[t.item]} ${t.quantity}개</option>`).join('')}</select></label><fieldset><legend>칭찬 도장 고르기</legend>${Object.entries(stamps).map(([id,name],i)=>`<label class="stamp-choice"><input type="radio" name="stamp" value="${id}" ${i===0?'checked':''}>${name}</label>`).join('')}</fieldset><label>손글씨 느낌의 한 줄 후기<textarea id="reviewText" maxlength="200" rows="3" placeholder="고마운 마음을 200자 이내로 남겨 주세요." required></textarea></label><button class="primary" type="submit">도장 콩콩 · 후기 남기기</button></form>`:'<p class="local-caption">구매 완료한 거래마다 한 번 후기를 남길 수 있어요.</p>'}`;
      document.querySelectorAll('[data-seller]').forEach(b=>b.onclick=()=>{seller=b.dataset.seller;render()});if($('#reviewForm'))$('#reviewForm').onsubmit=e=>{e.preventDefault();feedback(economy.reviewTrade(Number($('#reviewTrade').value),document.querySelector('input[name="stamp"]:checked').value,$('#reviewText').value))};
    }
  }
  setInterval(()=>{if(economy.settleMarket()){toast('가판대 물건이 팔렸어요! 장터에서 판매 대금을 받아 주세요.');if($('#marketRoot')&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))render()}},1000);
  return {market};
})();
